import pandas as pd, numpy as np, json, itertools
files=['tutorial','round1','round2','bonus1','bonus2','bonus3']
ds={f:pd.read_csv('data/%s.csv'%f) for f in files}
req={}; opt={}
for f in files:
    cells=set(); ns=[]
    for r in ds[f].result:
        p=json.loads(r); cells.update((q['x'],q['y']) for q in p); ns.append(len(p))
    req[f]=len(cells); opt[f]=min(ns)
dm=pd.read_csv('data/demographics.csv'); complete=set(dm.dropna().user_id)
ids=list(set(ds['bonus3'].user_id))
rows=[]
for uid in ids:
    d={'user_id':uid}
    for f in files:
        p=json.loads(ds[f][ds[f].user_id==uid].iloc[0].result)
        d[f+'_pos']=len(p); d[f+'_steps']=len(p)-1; d[f+'_t']=p[-1]['t']
    rows.append(d)
df=pd.DataFrame(rows); df['demo']=df.user_id.isin(complete)
for sub,name in [(df,'all'),(df[df.demo],'demo')]:
    for useTut in [True,False]:
        fl=files if useTut else files[1:]
        T=sum(sub[f+'_t'] for f in fl)/1000
        for denom_name,denom in [('cells',sum(req[f] for f in fl)),('pos',sum(req[f]+1 for f in fl))]:
            pace=T/denom
            for oname,optv,act in [('pos',sum(opt[f] for f in fl),sum(sub[f+'_pos'] for f in fl)),
                                   ('steps',sum(opt[f]-1 for f in fl),sum(sub[f+'_steps'] for f in fl))]:
                o=optv/act
                r=np.corrcoef(pace.rank(pct=True),o.rank(pct=True))[0,1]
                print(name,'tut' if useTut else 'notut',denom_name,oname,round(r*r,5),len(sub))
"
